description:
Write `public readonly record struct Vec2<T>(T X, T Y) where T : INumber<T>` with:

- operators `+`, `-` (both vectors), `*` (a vector times a `T`) and unary `-`;
- `public T Dot(Vec2<T> other)` and `public T LengthSquared` (a property);
- `public static Vec2<T> Zero`;
- `public Vec2<TOther> As<TOther>() where TOther : INumber<TOther>` converting each part with `CreateChecked` (so `new Vec2<int>(3, 4).As<double>()` works and `new Vec2<int>(300, 0).As<byte>()` throws `OverflowException`).

starter.Solution.cs:
using System.Numerics;

public readonly record struct Vec2<T>(T X, T Y) where T : INumber<T>
{
}

solution.Solution.cs:
using System.Numerics;

public readonly record struct Vec2<T>(T X, T Y) where T : INumber<T>
{
    public static Vec2<T> Zero => new(T.Zero, T.Zero);

    public static Vec2<T> operator +(Vec2<T> a, Vec2<T> b) => new(a.X + b.X, a.Y + b.Y);
    public static Vec2<T> operator -(Vec2<T> a, Vec2<T> b) => new(a.X - b.X, a.Y - b.Y);
    public static Vec2<T> operator -(Vec2<T> v) => new(-v.X, -v.Y);
    public static Vec2<T> operator *(Vec2<T> v, T k) => new(v.X * k, v.Y * k);

    public T Dot(Vec2<T> other) => X * other.X + Y * other.Y;
    public T LengthSquared => Dot(this);

    public Vec2<TOther> As<TOther>() where TOther : INumber<TOther>
        => new(TOther.CreateChecked(X), TOther.CreateChecked(Y));
}

unitTests:
Test("arithmetic with ints", () =>
{
    var a = new Vec2<int>(1, 2);
    var b = new Vec2<int>(3, 4);
    CheckEq(a + b, new Vec2<int>(4, 6));
    CheckEq(b - a, new Vec2<int>(2, 2));
    CheckEq(-a, new Vec2<int>(-1, -2));
    CheckEq(a * 3, new Vec2<int>(3, 6));
});

Test("dot and length with doubles", () =>
{
    var v = new Vec2<double>(3, 4);
    CheckEq(v.LengthSquared, 25.0);
    CheckEq(v.Dot(new Vec2<double>(0.5, 0.5)), 3.5);
    CheckEq(Vec2<double>.Zero, new Vec2<double>(0, 0));
});

Test("works with decimal", () =>
{
    CheckEq(new Vec2<decimal>(0.1m, 0.2m) + new Vec2<decimal>(0.2m, 0.1m), new Vec2<decimal>(0.3m, 0.3m));
});

Test("conversion", () =>
{
    CheckEq(new Vec2<int>(3, 4).As<double>(), new Vec2<double>(3.0, 4.0));
    CheckThrows<OverflowException>(() => new Vec2<int>(300, 0).As<byte>());
});

